export const usersRelations = authRelations(users, ({ many }) => ({
    sessions: many(sessions),
    accounts: many(accounts),
    passkeys: many(passkeys),
}))

export const sessionsRelations = authRelations(sessions, ({ one }) => ({
    user: one(users, {
        fields: [sessions.userId],
        references: [users.id],
    }),
}))

